import{_ as a,o as i,c as n,a2 as s}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Progresión del personaje","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/characters/progression.md","filePath":"es/game-design/characters/progression.md"}'),o={name:"es/game-design/characters/progression.md"};function r(t,e,d,c,l,p){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="character-progression" tabindex="-1">Progresión del personaje <a class="header-anchor" href="#character-progression" aria-label="Enlace permanente a &quot;Progresión del personaje&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; las preguntas abiertas permanecen Sin resolver. Las decisiones citadas con estado Aceptado conservan su alcance existente. <strong>Implementación/disponibilidad:</strong> no hay cambios en gameplay ni en configuración de ejecución; no se ha establecido que este rediseño esté activo. <strong>Verificación:</strong> revisión documental, no prueba de juego; aquí no se establece la disponibilidad actual. <strong>Revisado:</strong> 2026-10-09 para la versión pública; se conservan el estado del diseño y las mecánicas de la especificación canónica.</p><p><a href="/Syrolands-Public/es/guide/characters/progression.html">Resumen para jugadores</a> · <a href="/Syrolands-Public/es/game-design/characters/progression.html">Progresión del personaje</a></p><h2 id="purpose-and-ownership" tabindex="-1">Propósito y responsabilidad <a class="header-anchor" href="#purpose-and-ownership" aria-label="Enlace permanente a &quot;Propósito y responsabilidad&quot;">​</a></h2><p><strong>Un personaje con poca habilidad es inexperto, no inoperante.</strong> Syrolands debería ser divertido desde el primer día. El entrenamiento repetitivo no debería ser un requisito para participar de forma útil; los fallos rutinarios con poca habilidad y el combate inicial lento son problemas que evitar, no un diagnóstico del juego realizado por esta tarea documental. Una habilidad de 20 ya debería permitir una participación significativa.</p><p>Más habilidad amplía la capacidad, consistencia, rango de dificultad y maestría. No debería limitarse a volver utilizable una actividad antes inservible. Esta página define la filosofía general de progresión; <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">Habilidades y límite</a> define rangos, aumento y enseñanza; <a href="/Syrolands-Public/es/game-design/characters/techniques-and-specialization.html">Técnicas</a>, la jerarquía de habilidad/conocimiento/camino; <a href="/Syrolands-Public/es/game-design/characters/character-creation.html">Creación de personajes</a>, las historias iniciales; y <a href="/Syrolands-Public/es/game-design/characters/stats.html">Estadísticas</a>, la capacidad de respuesta y su dirección.</p><p>El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a> conserva el descubrimiento, diarios, intercambio, producción y encargos específicos de los oficios. Sus enlaces existentes de entrada/progresión llevan a estas reglas compartidas del personaje en lugar de mantener una segunda tabla de aumento.</p><h2 id="character-skill-knowledge-and-player-mastery" tabindex="-1">Habilidad del personaje, conocimiento y maestría del jugador <a class="header-anchor" href="#character-skill-knowledge-and-player-mastery" aria-label="Enlace permanente a &quot;Habilidad del personaje, conocimiento y maestría del jugador&quot;">​</a></h2><p><strong>La habilidad determina la capacidad. El conocimiento determina las posibilidades/información. La maestría del jugador determina el rendimiento.</strong> El conocimiento crea opciones; la habilidad mejora la ejecución. Estos tres ejes continúan el modelo del Batch 01.</p><p>Dos jugadores con igual habilidad pueden rendir de forma distinta por su ejecución humana. Dos artesanos GM pueden conocer técnicas y materiales diferentes. Quien conoce un buen procedimiento puede necesitar suficiente capacidad del personaje para ejecutarlo de forma fiable. Aprender un dato fuera del juego no concede automáticamente conocimiento al personaje ni competencia técnica.</p><h2 id="specialization-without-one-optimal-template" tabindex="-1">Especialización sin una plantilla óptima única <a class="header-anchor" href="#specialization-without-one-optimal-template" aria-label="Enlace permanente a &quot;Especialización sin una plantilla óptima única&quot;">​</a></h2><p>El presupuesto aproximado de 700 puntos debería admitir entre tres y cinco especializaciones principales, habilidades de apoyo alrededor de 60–90 y utilidades de menor inversión, todo dentro del límite real. Ni exactamente siete habilidades GM ni catorce habilidades a 50 deberían ser la respuesta óptima universal.</p><p>Una inversión baja/media ofrece opciones útiles. Una inversión profunda concede capacidades diferenciadas, consistencia y acceso a situaciones más difíciles, de modo que repartir demasiado los puntos tenga un coste de oportunidad real. La maestría sigue siendo valiosa sin resultar necesaria para todos los caminos del juego avanzado.</p><p><strong>Ilustración, no configuración canónica:</strong> un cazador podría combinar Archery, Tracking, Animal Lore y Anatomy con Tactics, Tailoring, Healing y Camping a distintos valores inferiores a 100. Este ejemplo no aprueba ninguna asignación numérica ni conjunto obligatorio de habilidades. Los papeles existentes de Anatomy/Tactics/Healing requieren revisar en el futuro la percepción de inversión obligatoria, no un rediseño no solicitado aquí.</p><h2 id="mastery-and-multiple-endgames" tabindex="-1">Maestría y múltiples metas avanzadas <a class="header-anchor" href="#mastery-and-multiple-endgames" aria-label="Enlace permanente a &quot;Maestría y múltiples metas avanzadas&quot;">​</a></h2><p>El máximo normal propuesto es 100, sin progresión ordinaria a 120. El juego avanzado no es una actividad universal ni requiere 100 en todos los caminos. Conocimiento, completar Codex/diarios, técnicas/escuelas raras, exploración, reputación, desafíos, dominio de objetos/procesos, ejecución humana, participación en el mundo y progresión social/económica/política continúan más allá del aumento numérico de habilidad.</p><table tabindex="0"><thead><tr><th>Aspiración</th><th>Identidades ilustrativas, no sistemas definidos por este lote</th></tr></thead><tbody><tr><td>Marcial</td><td>Duelista reconocido, cazador de monstruos, especialista de batalla, comandante</td></tr><tr><td>Artesanal</td><td>Maestro herrero, maestro fabricante de arcos, alquimista de élite, chef famoso</td></tr><tr><td>Conocimiento / exploración</td><td>Erudito, cartógrafo, investigador mágico, archivista</td></tr><tr><td>Económica</td><td>Comerciante, propietario de taller, creador de redes comerciales, especialista inmobiliario</td></tr><tr><td>Política / social</td><td>Consejero, líder de facción, asesor real, líder de gremio, tabernero, organizador comunitario</td></tr></tbody></table><p>Estos ejemplos no autorizan sistemas políticos, de vivienda, cartografía o clases. La especialización debería surgir de inversión, conocimiento aprendido, práctica y reputación, sin bloqueos artificiales por clase.</p><h2 id="reconciliation-and-open-questions" tabindex="-1">Conciliación y preguntas abiertas <a class="header-anchor" href="#reconciliation-and-open-questions" aria-label="Enlace permanente a &quot;Conciliación y preguntas abiertas&quot;">​</a></h2><ul><li><a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html#reconciliation-and-open-questions">Marco de habilidades</a>: límite exacto, aumento, modelos especiales, maestros, interfaz y conversión del listado.</li><li><a href="/Syrolands-Public/es/game-design/characters/character-creation.html#open-questions">Creación</a>: competencias, conjuntos, valores iniciales, conocimiento/objetos/reputación y libertad futura.</li><li><a href="/Syrolands-Public/es/game-design/characters/techniques-and-specialization.html#open-questions">Técnicas</a>: enseñanza, custodia, persistencia y olvido.</li><li><a href="/Syrolands-Public/es/game-design/characters/stats.html#reconciliation-and-open-questions">Estadísticas</a>: límites, cadencia con DEX baja y separación entre habilidad y estadística.</li></ul><p>El comportamiento heredado no constituye un modelo de balance modificado. La autoridad del servidor con estado Aceptado, los <a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">papeles existentes de las habilidades</a> y el segmento actual de combate conservan su alcance. No existe una prueba de progresión ni un nuevo ADR con estado Aceptado para el Batch 02.</p>',21)])])}const h=a(o,[["render",r]]);export{u as __pageData,h as default};
